import { Incident } from "../../entities/incident";
import styles from "./IncidentsTable.module.css";

type Props = {
  incidents: Incident[];
};

export const IncidentsTable = ({ incidents }: Props) => {
  return (
    <table>
      <thead>
        <tr>
          <th>ID</th>
          <th>Дата</th>
          <th>Приоритет</th>
          <th>Описание</th>
          <th>Статус сервиса</th>
          <th>Статус тикета</th>
          <th>Филиал</th>
        </tr>
      </thead>
      <tbody>
        {incidents.map((i) => (
          <tr key={i.id}>
            <td>{i.id}</td>
            <td>{i.createdAt}</td>
            <td>{i.priority}</td>
            <td>{i.description}</td>
            <td>{i.serviceStatus}</td>
            <td>{i.ticketStatus}</td>
            <td>{i.branch}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};
